import{_ as e,o as r,c as t,a3 as o}from"./chunks/framework.Wx1CEKvH.js";const f=JSON.parse('{"title":"よくある質問","description":"","frontmatter":{"head":[["link",{"rel":"canonical","href":"https://eurekaffeine.github.io/sapphire-star-codex/ja-jp/faq/"}],["meta",{"property":"og:url","content":"https://eurekaffeine.github.io/sapphire-star-codex/ja-jp/faq/"}],["meta",{"property":"og:title","content":"よくある質問 | Sapphire Star Codex"}],["meta",{"property":"og:description","content":"Monster Hunter reference data and armor builds for Wilds, Rise with Sunbreak, and World with Iceborne."}]]},"headers":[],"relativePath":"ja-jp/faq/index.md","filePath":"ja-jp/faq/index.md"}'),i={name:"ja-jp/faq/index.md"};function n(h,a,l,d,p,s){return r(),t("div",null,[...a[0]||(a[0]=[o('<h1 id="よくある質問" tabindex="-1">よくある質問 <a class="header-anchor" href="#よくある質問" aria-label="Permalink to &quot;よくある質問&quot;">​</a></h1><h2 id="対応している作品は" tabindex="-1">対応している作品は？ <a class="header-anchor" href="#対応している作品は" aria-label="Permalink to &quot;対応している作品は？&quot;">​</a></h2><p>『モンスターハンターワイルズ』『ライズ＋サンブレイク』『ワールド＋アイスボーン』です。作品ごとにデータを分けています。ホームで作品を切り替えてください。</p><h2 id="今すぐダウンロードできますか" tabindex="-1">今すぐダウンロードできますか？ <a class="header-anchor" href="#今すぐダウンロードできますか" aria-label="Permalink to &quot;今すぐダウンロードできますか？&quot;">​</a></h2><p>App Store、Google Play、AppGallery の一般公開ページはまだありません。3つのネイティブアプリを開発中です。公開後は<a href="./../#download">入手セクション</a>に確認済みのリンクを掲載します。</p><h2 id="オフラインで使えますか" tabindex="-1">オフラインで使えますか？ <a class="header-anchor" href="#オフラインで使えますか" aria-label="Permalink to &quot;オフラインで使えますか？&quot;">​</a></h2><p>基本の図鑑データはアプリに同梱され、閲覧、検索、お気に入り、装備ツールは端末内で動作します。外部サイトの閲覧や今後のアプリ更新には通信が必要です。</p><h2 id="装備検索でできることは" tabindex="-1">装備検索でできることは？ <a class="header-anchor" href="#装備検索でできることは" aria-label="Permalink to &quot;装備検索でできることは？&quot;">​</a></h2><p>必要なスキルとレベルを選び、装備を固定・除外して組み合わせを検索できます。所持装飾品の数も指定可能です。ライズでは所持護石や傀異錬成防具に対応します。結果は作品のデータと条件に依存し、ダメージ計算機ではありません。</p><h2 id="対応言語は" tabindex="-1">対応言語は？ <a class="header-anchor" href="#対応言語は" aria-label="Permalink to &quot;対応言語は？&quot;">​</a></h2><p>日本語、英語、簡体字中国語、繁体字中国語です。未翻訳の項目は英語で表示します。このサイトの画像も、選択した言語に合わせて切り替わります。</p><h2 id="capcom-の公式アプリですか" tabindex="-1">CAPCOM の公式アプリですか？ <a class="header-anchor" href="#capcom-の公式アプリですか" aria-label="Permalink to &quot;CAPCOM の公式アプリですか？&quot;">​</a></h2><p>いいえ。このサイトは独立した非営利ファンプロジェクトのウェブサイトです。CAPCOM との関係や承認はありません。Monster Hunter、ゲームのアートワークとデータは CAPCOM Co., Ltd. に帰属します。</p><h2 id="協力するには" tabindex="-1">協力するには？ <a class="header-anchor" href="#協力するには" aria-label="Permalink to &quot;協力するには？&quot;">​</a></h2><p><a href="./../others/">このアプリについて</a>をご覧ください。データの修正には作品名、項目名、値、確認できる出典が役立ちます。</p>',15)])])}const u=e(i,[["render",n]]);export{f as __pageData,u as default};
